type FormData = {
    username: string
    email: string
    age: number
}

type Validators = {
    [K in keyof FormData]: (value: FormData[K]) => string | null
}

const validators: Validators = {
    username: v => (v.length >= 3 ? null : "Kamida 3 belgi"),
    email: v => (v.includes("@") ? null : "Email noto'g'ri"),
    age: v => (v >= 18 ? null : "18 dan katta bo'lishi kerak"),
}

function validate(data: FormData): string[] {
    const errors: string[] = []
    for (const key of Object.keys(validators) as (keyof FormData)[]) {
        const error = (validators[key] as (value: unknown) => string | null)(data[key])
        if (error) errors.push(`${key}: ${error}`)
    }
    return errors
}

console.log(validate({ username: "ali", email: "ali@mail.uz", age: 25 }))
console.log(validate({ username: "ab", email: "wrong", age: 15 }))

