type Getters<T> = {
    [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K]
}

type Setters<T> = {
    [K in keyof T as `set${Capitalize<string & K>}`]: (value: T[K]) => void
}

type Person = { name: string; age: number }

function createAccessors(person: Person): Getters<Person> & Setters<Person> {
    return {
        getName: () => person.name,
        getAge: () => person.age,
        setName: (value: string) => { person.name = value },
        setAge: (value: number) => { person.age = value },
    }
}

const person = { name: "Ali", age: 30 }
const accessors = createAccessors(person)

console.log(accessors.getName(), accessors.getAge())
accessors.setName("Vali")
accessors.setAge(31)
console.log(accessors.getName(), accessors.getAge())

